import { Link } from '@tanstack/react-router';
import { useProjects } from './projects';

// The projects list. Reads server data straight from its query key and shows the client's NAME
// (served alongside each project), not the id.
export function ProjectList() {
  const { data: projects } = useProjects();

  if (!projects) {
    return null;
  }

  if (projects.length === 0) {
    return <p data-testid="projects-empty">No projects yet.</p>;
  }

  return (
    <table data-testid="projects-table">
      <thead>
        <tr>
          <th>Name</th>
          <th>Client</th>
          <th></th>
        </tr>
      </thead>
      <tbody>
        {projects.map((project) => (
          <tr key={project.id} data-testid={`project-row-${project.id}`}>
            <td data-testid="project-name">{project.name}</td>
            <td data-testid="project-client">{project.clientName}</td>
            <td>
              <Link
                to="/projects/$projectId"
                params={{ projectId: String(project.id) }}
                data-testid={`project-open-${project.id}`}
              >
                Open
              </Link>
            </td>
          </tr>
        ))}
      </tbody>
    </table>
  );
}
import { asString, useSearchParam } from '../../url/useSearchParam';
import { ClientSearch } from './ClientSearch';
import { useClients } from './clients';

// The clients list. Reads server data straight from its query key — never copied into state, never
// handed down from a parent. The name filter lives in the URL (`clientSearch`), read directly here;
// the search box owns that same key, so the two stay in step without any import between them.
export function ClientList() {
  const { data: clients } = useClients();
  const [query] = useSearchParam('clientSearch', asString);

  if (!clients) {
    return null;
  }

  if (clients.length === 0) {
    return (
      <>
        <ClientSearch />
        <p data-testid="clients-empty">No clients yet.</p>
      </>
    );
  }

  const needle = query.trim().toLowerCase();
  const visible = needle
    ? clients.filter((client) => client.name.toLowerCase().includes(needle))
    : clients;

  return (
    <>
      <ClientSearch />
      <table data-testid="clients-table">
      <thead>
        <tr>
          <th>Name</th>
          <th>Email</th>
        </tr>
      </thead>
      <tbody>
        {visible.map((client) => (
          <tr key={client.id} data-testid={`client-row-${client.id}`}>
            <td data-testid="client-name">{client.name}</td>
            <td data-testid="client-email">{client.email}</td>
          </tr>
        ))}
        </tbody>
      </table>
    </>
  );
}

